// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    address depositor = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;

    function setUp() public { c = new L1Block(); }

    function testFuzz_property(uint64 _number, uint64 _timestamp) public {
        vm.prank(depositor);
        c.setL1BlockValues(
            _number,
            _timestamp,
            1 ether,
            bytes32(uint256(0x1234)),
            uint64(7),
            bytes32(uint256(0x5678)),
            100,
            200
        );

        assertTrue(c.timestamp() == _timestamp);
    }
}
